import json

def process_configuration(json_text):
    try:
        config_data = json.loads(json_text)
    except json.JSONDecodeError as e:
        raise ValueError("Malformed JSON") from e

    if not isinstance(config_data, dict):
        raise ValueError("JSON content must be a dictionary.")

    if "retry_count" not in config_data:
        config_data["retry_count"] = 3

    return config_data
